package main

// The five noise() palettes (from ledsgo, which gets them from FastLED's
// colorpalettes.cpp), stored as constant strings: 16 RGBA entries, four bytes
// each. See gen_flags.py / flags.go for the same trick and why: the ledsgo
// Palette16 values as plain vars would need ~1.3 kB of RAM for read-only
// data, the same bytes again as a .data image, and ~330 B of init code to
// copy them.
//
// Generated by gen_palettes.py from the ledsgo module source; regenerate
// rather than editing by hand.

// palette16At returns the palette color at a 16-bit position, interpolating
// between neighbours and wrapping at the top. Bit-identical to
// ledsgo.Palette16.ColorAt.
func palette16At(p string, position uint16) (r, g, b uint8) {
	index := position >> 12
	next := index + 1
	if index >= 15 {
		next = 0
	}
	frac := uint8(position >> 4)
	r = blend8(uint8(p[index*4]), uint8(p[next*4]), frac)
	g = blend8(uint8(p[index*4+1]), uint8(p[next*4+1]), frac)
	b = blend8(uint8(p[index*4+2]), uint8(p[next*4+2]), frac)
	return r, g, b
}

// blend8 mixes top into bottom by topAlpha. Identical arithmetic to
// ledsgo.blend for 32-bit targets.
func blend8(bottom, top, topAlpha uint8) uint8 {
	bottomPart := int(bottom) * (255 - int(topAlpha))
	topPart := int(top) * int(topAlpha)
	return uint8((bottomPart + topPart + 255) / 256)
}

